//! 🏔️ Three handwritten native fields retain exact IEEE state and all five child identity strings.
use super::GisTerrainSnapshot;
#[derive(semio_framework_dsl_record_derive::DslRecord)]
struct Child{child_id:String,artifact_id:String,artifact_kind:String,standard:String,subset:String}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
struct Terrain{exaggeration:f64,imported_map:Option<crate::schema::ImportedMap>,mesh:Option<Child>}
#[path="🛫️encode/🦀️.rs"]mod controlled_output;
pub(super) fn producer()->semio_framework_dsl_record::RecordSpecProducer{Terrain::__dsl_spec_producer()}
pub(super) fn encode_record_controlled(snapshot:&GisTerrainSnapshot,c:&mut semio_framework_value::NativeEncodeControl<'_>)->Result<semio_framework_dsl_record::RecordValue,semio_framework_value::ValueError>{controlled_output::project(snapshot,c)}
impl Terrain{
 fn from_snapshot(value:&GisTerrainSnapshot)->Self{Self{exaggeration:value.exaggeration,imported_map:value.imported_map.clone(),mesh:value.mesh.as_ref().map(|c|Child{child_id:c.child_id.clone(),artifact_id:c.target.artifact_id.clone(),artifact_kind:c.target.dialect.artifact_kind.clone(),standard:c.target.dialect.standard.clone(),subset:c.target.dialect.subset.clone()})}}
 fn into_snapshot(self)->GisTerrainSnapshot{GisTerrainSnapshot{exaggeration:self.exaggeration,imported_map:self.imported_map,mesh:self.mesh.map(|c|store::ArtifactChild::new(c.child_id,store::os_io::ArtifactRef{artifact_id:c.artifact_id,dialect:store::os_io::ArtifactDialect{artifact_kind:c.artifact_kind,standard:c.standard,subset:c.subset}}))}}
}
impl store::ArtifactDsl for GisTerrainSnapshot{
 const EXTENSION:&'static str="gisterrain";
 fn envelope_id()->&'static str{"gis.gisterrain"}
 fn print_dsl(&self)->String{let body=semio_framework_dsl_record::print(&Terrain::from_snapshot(self).__dsl_to_record(),&Terrain::__dsl_spec(),semio_framework_dsl_record::JoinMode::Document);let envelope=store::semio_format::SemioEnvelope::from_envelope_id(Self::envelope_id(),store::semio_format::Component::Dsl,1).expect("terrain envelope");store::semio_format::wrap_text(&envelope,&body)}
 fn parse_dsl(text:&str)->Result<Self,semio_framework_diagnostic::TextError>{let(envelope,body)=store::semio_format::split_text_preamble(text).map_err(|e|semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;if !envelope.matches_identity(Self::envelope_id(),store::semio_format::Component::Dsl,1){return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "terrain native text identity differs", semio_framework_diagnostic::TextSpan::at(1, 1)))}let record=semio_framework_dsl_record::parse_exact(body,&Terrain::__dsl_spec(),&semio_framework_dsl_record::ParseOptions{limits:semio_framework_diagnostic::Limits::default(),mode:semio_framework_dsl_record::SourceMode::Document})?;let snapshot=Terrain::__dsl_from_record(&record)?.into_snapshot();if let Some(map)=&snapshot.imported_map{map.validate().map_err(|message| semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, message, semio_framework_diagnostic::TextSpan::at(1, 1)))?;}Ok(snapshot)}
}
impl store::ArtifactPack for GisTerrainSnapshot{
 fn sqlite_snapshot_codec()->Option<store::ArtifactSqliteSnapshotCodec>{Some(<Self as store::ArtifactSqliteSnapshot>::sqlite_codec())}
 fn record_spec()->Option<semio_framework_dsl_record::RecordSpec>{Some(Terrain::__dsl_spec())}
 fn encode_pack_with(&self,options:&store::PackEncodeOptions)->Result<Vec<u8>,store::PackError>{let inner=store::pack_rt::encode_document(&Terrain::__dsl_spec(),&Terrain::from_snapshot(self).__dsl_to_record(),options)?;let envelope=store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(),store::semio_format::Component::Pack,1).map_err(|e| store::PackError::from(e.into_value_error()))?;Ok(store::semio_format::wrap_binary(&envelope,&inner))}
 fn decode_pack_with(bytes:&[u8],options:&store::PackDecodeOptions)->Result<Self,store::PackError>{let(envelope,inner)=store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::from(e.into_value_error()))?;if !envelope.matches_identity(<Self as store::ArtifactDsl>::envelope_id(),store::semio_format::Component::Pack,1){return Err(store::PackError::from(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "terrain native binary identity differs")))}let(record,_)=store::pack_rt::decode_document(&inner,&Terrain::__dsl_spec(),options)?;let snapshot=Terrain::__dsl_from_record(&record).map_err(store::text_error_to_pack_error)?.into_snapshot();if let Some(map)=&snapshot.imported_map{map.validate().map_err(|detail| store::PackError::Refusal(store::PackRefusal::Malformed { kind: semio_framework_value::ValueRefusalKind::InvalidValue, what: "pack", offset: 0, detail }))?;}Ok(snapshot)}
}

pub(super) fn reconstruct_record_controlled(source:&semio_framework_dsl_record::RecordValue,control:&mut semio_framework_value::NativeDecodeControl<'_>,maximum_rows:usize,maximum_value_bytes:usize)->Result<GisTerrainSnapshot,semio_framework_value::ValueError>{control.checkpoint()?;super::row_admission::native(source,maximum_rows,||control.checkpoint())?;super::value_admission::native(source,maximum_value_bytes,control)?;let snapshot=Terrain::__dsl_from_record_controlled(source,control)?.into_snapshot();if let Some(map)=&snapshot.imported_map{map.validate().map_err(|error|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,error))?;}Ok(snapshot)}
